import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  interpolateColors,
  spring,
  random,
} from '../remotionShim';
// --- Font Loader Pattern ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// --- End Font Loader ---

// --- Schema Definition ---


export type FortniteMissionScreenProps = Record<string, any>;

// --- Helper Components ---

const ConfettiParticle: React.FC<{
  seed: number;
  colors: string[];
  width: number;
  height: number;
  frame: number;
}> = ({ seed, colors, width, height, frame }) => {
  const randomX = random(seed) * width;
  const randomDelay = random(seed + 1) * 20;
  const size = interpolate(random(seed + 2), [0, 1], [10, 25]);
  const color = colors[Math.floor(random(seed + 3) * colors.length)];
  const speed = interpolate(random(seed + 4), [0, 1], [0.5, 1.5]);
  const rotationSpeed = interpolate(random(seed + 5), [0, 1], [-5, 5]);

  const y = interpolate(
    frame,
    [0, 300], // Extend range to ensure continuous fall
    [-100 - randomDelay * 10, height + 200], // Start above, end below
    { extrapolateRight: "extend" }
  );

  const xOffset = Math.sin((frame + randomDelay) * 0.1) * 40 * speed;
  const rotation = frame * rotationSpeed;

  const currentY = y * speed;

  // Opacity fade in
  const opacity = interpolate(
    frame,
    [0, 20],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <div
      style={{
        position: "absolute",
        left: randomX + xOffset,
        top: currentY,
        width: size,
        height: size * 0.6,
        backgroundColor: color,
        transform: `rotate(${rotation}deg)`,
        opacity,
        borderRadius: size * 0.2,
      }}
    />
  );
};

// --- Main Component ---
const FortniteMissionScreen: React.FC<FortniteMissionScreenProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = true,
  durationInSeconds = 6,
  titleText = "BIKE CLEAN COMPLETED!",
  reward1 = "Chain Lubed +5",
  reward2 = "Frame Shine +10",
  reward3 = "Respect +++",
  reward4 = "Morale Boost +7",
  primaryColor = "#FFE900", // Fortnite Yellow
  secondaryColor = "#9F55FF", // Epic Purple
  accentColor = "#00D4FF", // Blue/Cyan
  titleSize = 80,
  confettiAmount = 50,
}) => {
  useFontLoader(["Luckiest Guy", "Carter One"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground
    ? backgroundColor.length === 9
      ? backgroundColor
      : `${backgroundColor}00`
    : backgroundColor;

  // --- Animations ---

  // Title Animation: Punch in with spring + slight tilt
  const titleDelay = 5;
  const titleSpring = spring({
    frame: frame - titleDelay,
    fps,
    config: { damping: 12, stiffness: 150, mass: 0.8 },
  });
  
  const titleScale = interpolate(titleSpring, [0, 1], [0, 1]);
  // Add a slight "slam" rotation effect
  const titleRotate = interpolate(
    frame - titleDelay,
    [0, 5, 15],
    [-10, 3, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const titleGlow = interpolate(
    Math.sin(frame / 10),
    [-1, 1],
    [10, 20]
  );

  // Rewards Animation: Staggered fold out
  const rewards = [reward1, reward2, reward3, reward4].filter(Boolean);
  const baseRewardDelay = 25;
  const stagger = 10;

  // Confetti generation
  const confettiParticles = useMemo(() => {
    return new Array(confettiAmount).fill(0).map((_, i) => i);
  }, [confettiAmount]);

  const confettiPalette = [primaryColor, secondaryColor, accentColor, "#FFFFFF"];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Background radial burst if not transparent, else empty */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            background: `radial-gradient(circle at center, ${secondaryColor}44 0%, ${backgroundColor} 100%)`,
          }}
        />
      )}

      {/* Confetti Layer (Behind Text) */}
      <AbsoluteFill>
        {confettiParticles.map((i) => (
          <ConfettiParticle
            key={i}
            seed={i}
            colors={confettiPalette}
            width={width}
            height={height}
            frame={frame}
          />
        ))}
      </AbsoluteFill>

      {/* Main Content Container */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
          gap: 40,
        }}
      >
        {/* Title */}
        <div
          style={{
            fontFamily: "Luckiest Guy",
            fontSize: titleSize,
            color: "white",
            textTransform: "uppercase",
            textAlign: "center",
            lineHeight: 1,
            transform: `scale(${titleScale}) rotate(${titleRotate}deg)`,
            textShadow: `
              4px 4px 0px #000, 
              -2px -2px 0px #000,
              0px 0px ${titleGlow}px ${primaryColor}
            `,
            // Removed parent stroke to make text cleaner/less bold
            position: "relative",
            zIndex: 10,
          }}
        >
          {/* Inner Gradient Text Effect */}
          <span
            style={{
              background: `linear-gradient(to bottom, ${primaryColor} 0%, ${interpolateColors(frame, [0, 60], ["#FFA500", "#FF4500"])} 100%)`,
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              filter: "drop-shadow(4px 4px 0px rgba(0,0,0,0.5))",
            }}
          >
            {titleText}
          </span>
          {/* Duplicate for stroke effect since background-clip: text messes with strokes */}
          <span
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              zIndex: -1,
              WebkitTextStroke: "4px black", // Reduced from 8px to 4px for better readability
              color: "transparent",
            }}
          >
            {titleText}
          </span>
        </div>

        {/* Rewards Container */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 15,
            perspective: "1000px", // Enable 3D folds
          }}
        >
          {rewards.map((text, index) => {
            const currentDelay = baseRewardDelay + index * stagger;
            
            // Animation for each item
            const itemSpring = spring({
              frame: frame - currentDelay,
              fps,
              config: { damping: 15, stiffness: 120 },
            });

            // Fold out effect (rotateX 90 -> 0)
            const rotateX = interpolate(itemSpring, [0, 1], [90, 0]);
            const opacity = interpolate(itemSpring, [0, 0.5], [0, 1]);
            const scale = interpolate(itemSpring, [0, 1], [0.8, 1]);
            
            // Determine color based on index for variety
            const itemColor = index % 2 === 0 ? secondaryColor : accentColor;

            return (
              <div
                key={index}
                style={{
                  fontFamily: "Carter One",
                  fontSize: titleSize * 0.4,
                  color: "white",
                  backgroundColor: "rgba(0, 0, 0, 0.6)",
                  padding: "10px 30px",
                  borderRadius: 10,
                  border: `3px solid ${itemColor}`,
                  boxShadow: `0px 5px 0px ${itemColor}, 0px 10px 10px rgba(0,0,0,0.3)`,
                  transform: `rotateX(${rotateX}deg) scale(${scale})`,
                  transformOrigin: "top center",
                  opacity,
                  minWidth: width * 0.4,
                  textAlign: "center",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  whiteSpace: "nowrap",
                }}
              >
                {/* Decorative Icon Placeholder (Circle) */}
                <div 
                  style={{
                    width: 15,
                    height: 15,
                    borderRadius: "50%",
                    backgroundColor: itemColor,
                    marginRight: 15,
                    boxShadow: "0 0 5px white"
                  }} 
                />
                {text}
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default FortniteMissionScreen;